import type {ModelBakeMemory} from './model-baked-runtime';
const f=Math.fround,add=(a:number,b:number)=>f(a+b),sub=(a:number,b:number)=>f(a-b),mul=(a:number,b:number)=>f(a*b),div=(a:number,b:number)=>f(a/b);
/** Original FlowerBarn.Initialize's generated 32² RG texture. Red is the
 * radial smootherstep profile, green is the narrow blade. FlowerAtlas is a
 * different resource; this texture is generated by the actual Barn. */
export function generateOriginalFlowerTexture():Uint8Array{
 const out=new Uint8Array(32*32*2);
 for(let y=0;y<32;y++){
  const py=div(add(y,-15.5),31),blade=mul(f((0.55-py)*2),f(255.9));
  for(let x=0;x<32;x++){
   const px=div(add(x,-15.5),31),s=Math.min(1,Math.max(0,div(add(add(mul(px,px),mul(py,py)),f(-.1)),f(.15))));
   const cube=mul(s,mul(s,s)),polynomial=mul(cube,add(mul(s,add(mul(s,6),-15)),10)),radial=mul(sub(1,polynomial),f(255.9)),at=(y*32+x)*2;
   out[at]=Math.trunc(Math.min(255,Math.max(0,radial)));out[at+1]=Math.trunc(Math.min(255,Math.max(0,Math.abs(px)>f(.2)?0:blade)));
  }
 }
 return out;
}
export interface FlowerTextureServices {
 initializeSampler(out:bigint,descriptor:Uint8Array):void;
 allocator():bigint;heap():bigint;allocate(owner:bigint,bytes:number,heap:bigint,alignment:number):bigint;free(owner:bigint,p:bigint):void;
 createImage(out:bigint,name:'FlowerTex',kind:number,width:number,height:number,format:number,flags:number):void;
 upload(out:bigint,pixels:bigint):void;finalizeImage(out:bigint):void;
}
/** Whole normal FlowerBarn.Initialize 0x10034e2b0 with the verified generated
 * bytes, actual image/sampler and allocator services supplied by their owners. */
export function initializeOriginalFlowerTexture(m:ModelBakeMemory,barn:bigint,s:FlowerTextureServices){
 m.write32(barn+0x11dc0n,0);
 const descriptor=Uint8Array.from('02000000020000000200000000000000000000000200000018fcffffe803000001000000'.match(/../g)!,h=>parseInt(h,16)),sampler=barn+0x455e60n,image=barn+0x455de8n;
 s.initializeSampler(sampler,descriptor);const allocator=s.allocator(),heap=s.heap(),pixels=s.allocate(allocator,0x800,heap,1);
 s.createImage(image,'FlowerTex',1,32,32,4,0);m.bytes(pixels,0x800).set(generateOriginalFlowerTexture());m.write64(image+8n,sampler);
 s.upload(image,pixels);s.finalizeImage(image);s.free(s.allocator(),pixels);
}
